"""Qualify the focused r30 startup repair from executed results and immutable inputs."""
import base64,hashlib,html,json,zipfile
from pathlib import Path
from datetime import datetime,timezone
R=Path(__file__).resolve().parents[2];W=R.parents[1];O=W/'deliverables';P=R/'r30-report';P.mkdir(exist_ok=True)
def read(n):return json.loads((R/n).read_text())
def sha(p):
 with p.open('rb')as f:return hashlib.file_digest(f,'sha256').hexdigest()
b=read('android/evidence/build-r30-001/BUILD_RECEIPT.json');apk=O/'Project1998-r30-update-arm64.apk';assert b['status']=='BUILD_PASS'and sha(apk)==b['sha256']and b['version_code']==34
assert b['package']=='com.irewon.project1998.g1bv4'and b['certificate_sha256']=='ecea13778e2466b3e568f45bfe1facb6fd708bdd0ed3f6ae2a4c305da2ebb030'
cases=[('Mixed legacy catalog, recovery and refusal safety','evidence/r24/runtime/r30-catalog-final001/RESULT.json',15),('Original position-only recovery and failure guards','evidence/r24/runtime/r30-recovery-final001/RESULT.json',17),('Whole backup, restore and normal login','evidence/r24/runtime/r30-backup-final001/RESULT.json',6),('Actual Godot selection, recovery, floor tap, return and reopen','evidence/r30/ui/final004/runtime/ko-checks.json',8)]
for _,path,count in cases:
 j=read(path);assert j['status'].startswith('PASS')and len(j['checks'])==count and all(c['status']=='PASS'for c in j['checks'])
x=read('evidence/r30/XUNIT-COMPARISON.json');assert x['status']=='PASS_NO_NEW_FAILURES'
freeze=read('verification/r30/RELEASE-PRODUCTS.json');assert all(sha(R/n)==h for n,h in freeze['source'].items())
base=W/'deliverables/Project1998-r29-source-tests.zip';assert sha(base)=='33384b1f0b8650dfc19b8e6e781b7f8f7297e604eecd88caa4f5eb15a6a78855'
with zipfile.ZipFile(base)as z:
 changed=[n for n in freeze['source']if sha(R/n)!=hashlib.sha256(z.read('source/'+R.name+'/'+n)).hexdigest()]
 content=[n for n in z.namelist()if n.startswith('source/'+R.name+'/candidate/game-data/')and not n.endswith('/')]
 assert sorted(changed)==['Host/OfflineBackupStore.cs','android/Main.cs']and len(content)==8056
 assert all((R/n.split(R.name+'/',1)[1]).read_bytes()==z.read(n)for n in content)
limitations=['Actual user save DB and physical Android r30 execution NOT_RUN. The actual r28 diagnostic catalog and supplied r29 failure screenshot are evidence; the passing recovery uses separate generated saves.','Original xUnit66 failures remain FAIL with identical names/messages; no new failures. Full world and thermal limitations from r29 remain.','Earlier development fixtures that staged then detached legacy credentials showed conflicting credential rediscovery; these are retained as failed development attempts, not device evidence. The final fixture creates legacy probe accounts directly without ever archiving credentials, matching HostProbe and the supplied diagnostic.','Initial fixture also seeded level17 with level1 derived AC and read the restored DB through the process-default CharacterStore constructor. Both test errors were corrected without weakening any preservation assertion; original Arrival derives AC as100-level.']
result={'schema':'P1998_R30_STARTUP_BACKUP_REPAIR_1','generated_utc':datetime.now(timezone.utc).isoformat(),'status':'SIGNED_UPDATE_READY_SCOPED_DEVICE_NOT_RUN','build':b,'root_cause':'r29 recovery uses a whole backup validator requiring every account to have an archived credential. Actual supplied diagnostic lists gibprobe/gionetest as CREDENTIAL_UNAVAILABLE and totogo as CanOpen. The same catalog reproduces reported_position_recovery/Backup profiles and saved accounts are incomplete or inconsistent.','source_changes':changed,'fix':'Allow readable database-only legacy rows to remain unavailable while preserving their DB data. The selected character must authenticate; metadata warnings, SQLite integrity, every JSON/watermark, hashes, exclusive ownership and no-overwrite restore stay enforced. No credential is invented or account deleted.','cases':[{'name':name,'checks':count,'status':'PASS','evidence':path}for name,path,count in cases],'xunit':{'executed':x['current']['executed'],'passed':x['current']['passed'],'failed':x['current']['failed'],'new':x['new_failure_names'],'changed':x['changed_failure_messages']},'content_files_unchanged_from_r29':8056,'reused_r29_evidence':'All UI, Server rules and content source bytes are identical; prior render and UI seven-issue evidence stays scoped to its original execution. Main BuildId and BackupStore are the only changed runtime CS files. A new actual Main login/recovery/tap/reopen test executes the changed startup path.','limitations':limitations,'actual_user_save_recovery':'NOT_RUN_UNTIL_INSTALLED_AND_TOTOGO_CONTINUE','physical_android':'NOT_RUN','user_save_writes_in_this_workspace':0}
(P/'Project1998-r30-results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
e=lambda s:html.escape(str(s));rows=''.join('<tr><td>'+e(name)+'</td><td>'+str(count)+' PASS</td><td>'+e(path)+'</td></tr>'for name,path,count in cases)
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Project1998 r30 진입 실패 보수</title><style>body{font:16px/1.7 system-ui;max-width:1050px;margin:28px auto;padding:0 18px;color:#302719;background:#f5f0e7}table{border-collapse:collapse;width:100%;background:white}td,th{border:1px solid #c7b697;padding:10px;text-align:left}img{max-width:100%;height:auto}.notice{background:#fff0b9;padding:16px}li{margin:10px 0;overflow-wrap:anywhere}</style><h1>r30 · totogo 진입 실패 수정</h1><p>r29에서 제가 추가한 복구 백업 검사가 진입을 막았습니다. 제공된 기존 진단에 이미 있던 암호 없는 검사 캐릭터2개를 시험에서 빠뜨린 것이 원인이었습니다.</p><p class="notice">기존 앱 위에 r30 APK를 업데이트 설치하고 totogo 이어하기를 선택하세요. 저장이 지도1014 (0,17), 레벨17이면 전체 백업 후 위치만 부여성330 (29,143)으로 복구합니다. 패키지·인증서·저장 폴더를 유지합니다. 사용자의 실제 DB를 이 환경에서 수정한 것은 아니며 실제 기기 적용은 NOT_RUN입니다.</p><h2>확인한 원인과 변경</h2><p>기존 진단의 gibprobe·gionetest는 CREDENTIAL_UNAVAILABLE이고 totogo는 정상 로그인 가능합니다. 이 구성을 만든 실제 원래 로그인에서 reported_position_recovery 단계의 ‘Backup profiles and saved accounts are incomplete or inconsistent’를 재현했습니다. r30은 해당 과거 DB 계정도 삭제하거나 암호를 만들지 않고 그대로 백업·복원합니다. 선택한 캐릭터의 인증, JSON/진행도 기록, SQLite 무결성, 전체 파일 해시, 전용 잠금과 기존 저장 덮어쓰기 금지는 유지합니다.</p><h2>실행 검증</h2><table><tr><th>검사</th><th>결과</th><th>근거</th></tr>'''+rows+'</table><p>전체 xUnit2093개:2027 PASS / 기존66 FAIL. 실패 이름·메시지 변경0, 신규0. 기존 UI·게임 규칙·8056데이터 파일은 r29와 동일하며 이전 유효 실행 근거는 새 실행으로 바꾸지 않고 재사용합니다.</p><h2>실제 PC Godot 입력 화면</h2><p>별도 시험 저장: 캐릭터 목록에서 totogo 선택 → 부여성 복구 → 바닥 한 번 터치 이동 → 종료 → 다시 이어하기. 실제 사용자 기기 화면은 아닙니다.</p><img alt="별도 저장의 실제 PC 복구 실행" src="data:image/png;base64,'+base64.b64encode((R/'evidence/r30/ui/final004/runtime/r30-totogo-buya.png').read_bytes()).decode()+'"><h2>설치 파일</h2><p>'+e(apk.name)+'<br>버전 code34 / '+e(b['version_name'])+'<br>SHA-256: '+e(b['sha256'])+'<br>기존 인증서: '+e(b['certificate_sha256'])+'</p><h2>제한과 개발 중 실패 기록</h2><ul>'+''.join('<li>'+e(s)+'</li>'for s in limitations)+'</ul><p>원래17개 위치 복구 검사와 이번15개 혼합 계정 검사가 위치 외 캐릭터 원문·모든 SQLite 테이블·다른 계정 보존을 대조했습니다. 보고서만으로 실기기 성공을 주장하지 않습니다.</p></html>'
(P/'Project1998-r30-report.html').write_text(page);(O/'Project1998-r30-report.html').write_text(page)
(R/'README-r30.txt').write_text('Project1998 r30 fixes r29 reported_position_recovery startup failure on a catalog containing database-only legacy probes. Active STATE: verification/r29/STATE.json. Full source extends delivered r29. Only BackupStore and Main BuildId runtime CS differ; all8056 content files preserved. New mixed-catalog15 and actual Godot select/recover/tap/return/reopen8, previous recovery17 and backup6 PASS. XUnit2093/2027PASS/66 unchanged FAIL. Device/actual-user-save application NOT_RUN. No credentials or player databases included.\n')
print(json.dumps({'status':result['status'],'apk_sha256':b['sha256'],'report':str(O/'Project1998-r30-report.html')}))
